void cut(const string& s, int start, vector<string>& path, vector<vector<string>>& res) {
    if (start == (int)s.size()) {
        res.push_back(path);
        return;
    }
    for (int i = start; i < (int)s.size(); i++) {
        if (!isPal(s, start, i)) {
            continue;
        }
        path.push_back(s.substr(start, i - start + 1));
        cut(s, i + 1, path, res);
        path.pop_back();
    }
}

