List<List<String>> solveNQueens(int n) {
    List<List<String>> res = new ArrayList<>();
    place(n, 0, new int[n], new HashSet<>(), new HashSet<>(), new HashSet<>(), res);
    return res;
}

void place(int n, int r, int[] queens, Set<Integer> cols, Set<Integer> diag, Set<Integer> anti, List<List<String>> res) {
    if (r == n) {
        List<String> board = new ArrayList<>();
        for (int c : queens) {
            char[] row = new char[n];
            Arrays.fill(row, '.');
            row[c] = 'Q';
            board.add(new String(row));
        }
        res.add(board);
        return;
    }
    for (int c = 0; c < n; c++) {
        if (cols.contains(c) || diag.contains(r - c) || anti.contains(r + c)) continue;
        queens[r] = c;
        cols.add(c);
        diag.add(r - c);
        anti.add(r + c);
        place(n, r + 1, queens, cols, diag, anti, res);
        cols.remove(c);
        diag.remove(r - c);
        anti.remove(r + c);
    }
}

